using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Unity.Collections;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class AlpsBorrowedScenery {
  const string Log="Logs/AlpsBorrowedScenery",Path="Assets/Scenes/TheAlps.unity";
  static AlpsBorrowedScenery(){EditorApplication.update+=Tick;}
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("Alps scenery: "+why);}
  static void Tick(){if(!File.Exists(Log+".request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;var action=File.ReadAllText(Log+".request").Trim();File.Delete(Log+".request");try{Directory.CreateDirectory(Log);if(action=="retry"){var active=SceneManager.GetActiveScene();if(active.isDirty)Check(EditorSceneManager.SaveScene(active,Log+"/Failed-unsaved-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true),"preserve failed authoring state");EditorSceneManager.OpenScene(Path);Install();}else if(action=="apply")Install();else if(action=="roof")RestoreBorrowedRoof();else if(action=="access")FinishAccess();else if(action=="review")Review();else Inspect();}catch(Exception e){File.WriteAllText(Log+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Bounds WorldBounds(GameObject go){var renderers=go.GetComponentsInChildren<Renderer>(true).Where(CatalogValidation.PrimaryForestGeometry).ToArray();if(renderers.Length==0)return new Bounds(go.transform.position,Vector3.zero);var b=new Bounds(go.transform.position,Vector3.zero);bool found=false;foreach(var r in renderers){var local=r.localBounds;for(int i=0;i<8;i++){var point=r.transform.TransformPoint(local.center+Vector3.Scale(local.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(!found){b=new Bounds(point,Vector3.zero);found=true;}else b.Encapsulate(point);}}return b;}
  static void Inspect(){var source=EditorSceneManager.OpenScene("Assets/Scenes/Pinefall.unity",OpenSceneMode.Additive);try{
   File.WriteAllLines(Log+"/SourceInventory.txt",All<CatalogPlacement>(source).Where(p=>!(p.assetId??"").StartsWith("alpine-tree-")).Select(p=>p.assetId+" | "+p.placementId+" | "+p.name+" | at "+p.transform.position.ToString("F3")+" rot "+p.transform.eulerAngles.ToString("F1")+" scale "+p.transform.lossyScale.ToString("F2")+" bounds "+WorldBounds(p.gameObject).ToString("F2")));
   var garage=All<CatalogPlacement>(source).Single(p=>p.placementId=="pinefall-garage");File.WriteAllLines(Log+"/GarageParts.txt",garage.GetComponentsInChildren<MeshRenderer>(true).Select(r=>r.name+" | "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name:"null"))+" | "+r.bounds.ToString("F2")));
  }finally{EditorSceneManager.CloseScene(source,true);}
   var s=SceneManager.GetSceneByPath(Path);Check(s.IsValid(),"Alps must be open");var terrain=All<Terrain>(s).Single();File.WriteAllLines(Log+"/TreeBefore.txt",All<CatalogPlacement>(s).Where(p=>(p.assetId??"").StartsWith("alpine-tree-")).Select(p=>p.placementId+" root "+p.transform.position.ToString("F2")+" minY "+WorldBounds(p.gameObject).min.y+" terrain "+(terrain.SampleHeight(p.transform.position)+terrain.transform.position.y)));
  }
  const string GroupName="Pinefall shared scenery | Alps placements";
  static float Ground(Terrain terrain,Vector3 at)=>terrain.SampleHeight(at)+terrain.transform.position.y;
  static bool Overlap(Bounds a,Bounds b,float gap=0)=>a.min.x<b.max.x+gap&&a.max.x>b.min.x-gap&&a.min.z<b.max.z+gap&&a.max.z>b.min.z-gap;
  static readonly Dictionary<string,Vector3[]> supports=new Dictionary<string,Vector3[]>();
  static Vector3[] Feet(GameObject tree){var key=tree.GetComponent<CatalogPlacement>().assetId;if(supports.TryGetValue(key,out var cached))return cached;var points=new List<Vector3>();foreach(var f in tree.GetComponentsInChildren<MeshFilter>(true).Where(CatalogValidation.PrimaryForestGeometry)){
   using(var raw=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh))using(var vertices=new NativeArray<Vector3>(raw[0].vertexCount,Allocator.Temp)){raw[0].GetVertices(vertices);var matrix=tree.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;foreach(var v in vertices)points.Add(matrix.MultiplyPoint3x4(v));}
  }float min=points.Min(p=>p.y);return supports[key]=points.Where(p=>p.y<min+.065f).Distinct().ToArray();}
  // Support points are transformed to world space before comparison with terrain.
  public static float SeatTree(GameObject tree,Terrain terrain){var at=tree.transform.position;at.y=0;tree.transform.position=at;float high=float.MinValue,low=float.MaxValue;foreach(var foot in Feet(tree)){var p=tree.transform.TransformPoint(foot);float y=Ground(terrain,p)-p.y;high=Mathf.Max(high,y);low=Mathf.Min(low,y);}at.y=high-.015f;tree.transform.position=at;return high-low;}
  static GameObject Copy(CatalogPlacement source,Transform parent,string id,Vector3 at,Quaternion rotation){var go=UnityEngine.Object.Instantiate(source.gameObject,parent);go.name=id+" | shared "+source.assetId;go.transform.SetPositionAndRotation(at,rotation);go.transform.localScale=source.transform.lossyScale;go.GetComponent<CatalogPlacement>().placementId=id;go.SetActive(true);foreach(var text in go.GetComponentsInChildren<TextMesh>(true))text.text=text.text.Replace("PINEFALL","THE ALPS").Replace("Pinefall","The Alps");return go;}
  static GameObject Place(CatalogPlacement source,Transform parent,string id,Vector3 at,Quaternion rotation,Terrain terrain){var go=Copy(source,parent,id,at,rotation);var b=WorldBounds(go);go.transform.position+=Vector3.up*(Ground(terrain,at)-b.min.y-.015f);return go;}
  static void Backup(){var active=SceneManager.GetActiveScene();if(active.isDirty)Check(EditorSceneManager.SaveScene(active,Log+"/Unsaved-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true),"unsaved scene backup");File.Copy(Path,Log+"/TheAlps-before.unity",true);}
  static void Install(){Backup();var scene=SceneManager.GetSceneByPath(Path);if(!scene.IsValid())scene=EditorSceneManager.OpenScene(Path);Check(!All<Transform>(scene).Any(t=>t.name==GroupName),"already installed; review existing placements instead of duplicating");var terrain=All<Terrain>(scene).Single();var town=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("THE ALPS |"));var parent=new GameObject(GroupName).transform;SceneManager.MoveGameObjectToScene(parent.gameObject,scene);parent.SetParent(town.transform,false);
   var source=EditorSceneManager.OpenScene("Assets/Scenes/Pinefall.unity",OpenSceneMode.Additive);try{var placements=All<CatalogPlacement>(source);CatalogPlacement Find(string id)=>placements.Single(p=>p.placementId==id);
    var oldDepot=All<Transform>(scene).Single(t=>t.name.StartsWith("Municipal alpine depot"));
    var garage=Copy(Find("pinefall-garage"),parent,"alps-garage",new Vector3(-96,5.15f,-107),Quaternion.identity);
    var gate=GateMaterial(garage);foreach(var r in garage.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("Door_")))r.sharedMaterial=gate;
    UnityEngine.Object.DestroyImmediate(oldDepot.gameObject);
    foreach(var old in All<Transform>(scene).Where(t=>t.name=="Diesel service island"||t.name=="Snow disposal yard"||t.name=="Alpine lantern").ToArray())UnityEngine.Object.DestroyImmediate(old.gameObject);
    // Yard keeps its accounting rectangle and open north entrance. Pump stays off the driving corridor.
    Copy(Find("pinefall-fuel-station"),parent,"alps-fuel-station",new Vector3(-111,5.15f,-81),Quaternion.identity);
    Copy(Find("pinefall-disposal-yard"),parent,"alps-disposal-yard",new Vector3(94,5.15f,-85),Quaternion.identity);
    int lamps=0;var lampSources=placements.Where(p=>(p.assetId??"").StartsWith("alpine-street-light-")).GroupBy(p=>p.assetId).Select(g=>g.First()).ToArray();var ids=new[]{"alpine-street-light-04","alpine-street-light-05","alpine-street-light-08"};
    foreach(float x in new[]{-57f,57})foreach(float z in new[]{-90f,-57,-25,8,57,88,105}){var model=lampSources.Single(p=>p.assetId==ids[lamps%ids.Length]);Place(model,parent,"alps-lamp-"+(++lamps),new Vector3(x,0,z),Quaternion.Euler(0,x>0?180:0,0),terrain);}
    foreach(var at in new[]{new Vector3(42,0,15),new Vector3(42,0,48),new Vector3(-6,0,48),new Vector3(76,0,-105)})Place(lampSources.Single(p=>p.assetId=="alpine-street-light-04"),parent,"alps-lamp-"+(++lamps),at,Quaternion.identity,terrain);
    Sign(Find("pinefall-sign-05"),parent,"alps-sign-directory",new Vector3(-8,0,8),new Vector3(-1,0,-1),terrain);
    Sign(Find("pinefall-sign-07"),parent,"alps-sign-depot",new Vector3(-106,0,-58),Vector3.back,terrain);
    Sign(Find("pinefall-sign-10"),parent,"alps-sign-fuel",new Vector3(-116,0,-75),Vector3.right,terrain);
    Sign(Find("pinefall-sign-12"),parent,"alps-sign-town",new Vector3(8,0,12),Vector3.left,terrain);
    var disposal=Sign(Find("pinefall-sign-10"),parent,"alps-sign-disposal",new Vector3(73,0,-77),Vector3.left,terrain);foreach(var text in disposal.GetComponentsInChildren<TextMesh>(true))text.text="SNOW STORAGE\nDRIVE IN + DUMP";
   }finally{EditorSceneManager.CloseScene(source,true);}
   ReseatForest(scene,terrain);Physics.SyncTransforms();ReconcileObstacles(scene);AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene),"save borrowed scenery");Review();
  }
  static Material GateMaterial(GameObject garage){const string folder="Assets/Snowglow/Levels/TheAlps/";if(!File.Exists(folder+"GarageGatePalette.png")){var texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes("Assets/Snowglow/Catalog/Sources/FourBaySnowGarage/Palette.png"));var colors=texture.GetPixels32();int changed=0;for(int i=0;i<colors.Length;i++){var c=colors[i];if(Mathf.Abs(c.r-221)<5&&Mathf.Abs(c.g-232)<5&&Mathf.Abs(c.b-236)<5){colors[i]=new Color32(202,118,103,c.a);changed++;}}Check(changed>0,"door palette swatch");texture.SetPixels32(colors);texture.Apply();File.WriteAllBytes(folder+"GarageGatePalette.png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(folder+"GarageGatePalette.png");}var importer=(TextureImporter)AssetImporter.GetAtPath(folder+"GarageGatePalette.png");importer.filterMode=FilterMode.Point;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();var path=folder+"GarageGates.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(garage.GetComponentsInChildren<MeshRenderer>().First().sharedMaterial){name="The Alps | Swiss red garage gates"};AssetDatabase.CreateAsset(mat,path);}mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"GarageGatePalette.png"));EditorUtility.SetDirty(mat);return mat;}
  static GameObject Sign(CatalogPlacement source,Transform parent,string id,Vector3 at,Vector3 facing,Terrain terrain){var go=Copy(source,parent,id,at,Quaternion.identity);var face=go.GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.id=="label-face").transform;var normal=go.transform.InverseTransformDirection(-face.forward);go.transform.rotation=Quaternion.LookRotation(facing)*Quaternion.Inverse(Quaternion.LookRotation(normal));var bounds=WorldBounds(go);go.transform.position+=Vector3.up*(Ground(terrain,at)-bounds.min.y-.015f);foreach(var old in go.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Authoring | road reading position").ToArray())UnityEngine.Object.DestroyImmediate(old.gameObject);return go;}
  static void ReseatForest(Scene scene,Terrain terrain){var trees=All<CatalogPlacement>(scene).Where(p=>(p.assetId??"").StartsWith("alpine-tree-")).OrderBy(p=>p.placementId).ToArray();var treeColliders=trees.SelectMany(t=>t.GetComponentsInChildren<Collider>(true)).ToArray();foreach(var c in treeColliders)c.enabled=false;Physics.SyncTransforms();var obstacles=All<Collider>(scene).Where(c=>c.enabled&&!c.isTrigger&&c.gameObject.activeInHierarchy&&!(c is TerrainCollider)&&!c.GetComponentInParent<MachineController>()&&!c.GetComponentInParent<SnowField>()&&!(c.transform.parent==terrain.transform.parent&&c is MeshCollider)).Select(c=>c.bounds).ToList();
   var peaks=All<Transform>(scene).Where(t=>t.name.StartsWith("Faceted ridge ")).Select(t=>WorldBounds(t.gameObject)).ToArray();var roads=All<MeshCollider>(scene).Where(c=>c.transform.parent&&c.transform.parent.name.StartsWith("THE ALPS |")&&c.gameObject.activeInHierarchy).ToArray();var accepted=new List<Bounds>();var random=new System.Random(81533);int moved=0;float worst=0;
   try{foreach(var tree in trees){var original=tree.transform.position;bool found=false;for(int attempt=0;attempt<12000;attempt++){float x=attempt==0?original.x:(float)random.NextDouble()*640-320,z=attempt==0?original.z:(float)random.NextDouble()*640-320;if(Mathf.Abs(x)<132&&Mathf.Abs(z)<132||new Vector2(x,z).magnitude>340)continue;tree.transform.SetPositionAndRotation(new Vector3(x,0,z),Quaternion.Euler(0,(float)random.NextDouble()*360,0));float spread=SeatTree(tree.gameObject,terrain);if(spread>.18f)continue;var b=WorldBounds(tree.gameObject);if(obstacles.Any(o=>Overlap(b,o,2))||peaks.Any(o=>Overlap(b,o,2))||accepted.Any(o=>Overlap(b,o,1.2f)))continue;
     bool nearRoad=false;for(int ix=-1;ix<=1;ix++)for(int iz=-1;iz<=1;iz++){var at=new Vector3(b.center.x+ix*(b.extents.x+3),200,b.center.z+iz*(b.extents.z+3));if(roads.Any(c=>c.Raycast(new Ray(at,Vector3.down),out var hit,250)))nearRoad=true;}if(nearRoad)continue;accepted.Add(b);worst=Mathf.Max(worst,spread);found=true;if(Vector2.Distance(new Vector2(x,z),new Vector2(original.x,original.z))>.1f)moved++;break;}Check(found,"no safe terrain seat for "+tree.placementId);var lod=tree.GetComponent<DistanceVisibility>();Check(lod&&lod.nearParts.Length>0&&lod.distantParts.Length>0,"retained geometry/card bindings");foreach(var r in lod.nearParts)r.enabled=true;foreach(var r in lod.distantParts)r.enabled=false;}
   }finally{foreach(var c in treeColliders)if(c)c.enabled=true;Physics.SyncTransforms();}
   File.WriteAllText(Log+"/Forest.txt",trees.Length+" existing Pinefall trees retained, "+moved+" relocated away from roads/buildings/peaks. All upright, transformed mesh-base support fitted to terrain; maximum support height spread "+worst+"m, 15mm seating overlap. Existing scale, solid colliders and 200m/2000m geometry/card settings retained.");
  }
  static void ReconcileObstacles(Scene scene){var snow=All<SnowField>(scene).Single();var original=snow.seed;var revised=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revised.grid.blocked.Length;i++){bool blocked=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(.22f,.65f,.22f),Quaternion.identity,1,QueryTriggerInteraction.Ignore);if(blocked!=revised.grid.blocked[i]){revised.grid.blocked[i]=blocked;changed++;}}
   if(changed>0){var oldMask=revised.grid.blocked;revised.grid.blocked=original.grid.blocked;Check(JsonUtility.ToJson(revised.grid)==JsonUtility.ToJson(original.grid),"snow quantity preservation");revised.grid.blocked=oldMask;AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Levels/TheAlps/BorrowedSceneryObstacles.asset"));snow.seed=revised;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revised);File.WriteAllText(Log+"/SnowMask.txt",changed+" obstacle flags updated in separate Alps seed revision. Original seed, snow depth/credit/volume preserved.");
  }
  static void FinishAccess(){var scene=EditorSceneManager.OpenScene(Path);File.Copy(Path,Log+"/TheAlps-before-access.unity",true);var parent=All<Transform>(scene).Single(t=>t.name==GroupName);var spur=All<MeshRenderer>(scene).SingleOrDefault(r=>r.name=="Disposal approach");var material=spur?spur.sharedMaterial:AssetDatabase.LoadAssetAtPath<Material>("Assets/Snowglow/Levels/TheAlps/Asphalt.mat");if(spur)UnityEngine.Object.DestroyImmediate(spur.gameObject);if(!parent.Find("North disposal entrance | paved connection"))PrimitiveKit.Cube("North disposal entrance | paved connection",parent,new Vector3(94,5.08f,-66.5f),new Vector3(10,.12f,9),material,true);Physics.SyncTransforms();ReconcileObstacles(scene);AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene),"save north yard entry");Review();}
  static void RestoreBorrowedRoof(){const string log="Logs/AlpsGarageRoof";Directory.CreateDirectory(log);var active=SceneManager.GetActiveScene();if(active.isDirty)Check(EditorSceneManager.SaveScene(active,log+"/Unsaved-before-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true),"preserve unsaved edits");File.Copy(Path,log+"/TheAlps-before.unity",true);var scene=SceneManager.GetSceneByPath(Path);if(!scene.IsValid())scene=EditorSceneManager.OpenScene(Path);
   var garage=All<CatalogPlacement>(scene).Single(p=>p.placementId=="alps-garage");int removed=0;foreach(var t in All<Transform>(scene).Where(t=>t.name.StartsWith("Alps retained roof |")).ToArray()){UnityEngine.Object.DestroyImmediate(t.gameObject);removed++;}var caps=garage.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("SnowCap")).ToArray();Check(caps.Length==1,"one original snow cap");foreach(var r in caps){r.gameObject.SetActive(true);r.enabled=true;}
   var source=EditorSceneManager.OpenScene("Assets/Scenes/Pinefall.unity",OpenSceneMode.Additive);try{var original=All<CatalogPlacement>(source).Single(p=>p.placementId=="pinefall-garage");var expected=original.GetComponentsInChildren<MeshFilter>(true);var actual=garage.GetComponentsInChildren<MeshFilter>(true);Check(expected.Length==actual.Length,"original garage mesh count");foreach(var f in expected){var matches=actual.Where(a=>a.name==f.name).ToArray();Check(matches.Length==1,"original mesh name "+f.name);var copy=matches[0];Check(copy.sharedMesh==f.sharedMesh,"shared original mesh "+f.name);var a=garage.transform.worldToLocalMatrix*copy.transform.localToWorldMatrix;var b=original.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;for(int i=0;i<16;i++)Check(Mathf.Abs(a[i]-b[i])<.0001f,"original mesh placement "+f.name);}}
   finally{EditorSceneManager.CloseScene(source,true);}Check(EditorSceneManager.SaveScene(scene),"save original borrowed roof");Review();File.Copy(Log+"/Depot.png",log+"/Depot.png",true);File.WriteAllText(log+"/Validation.txt","PASS: removed "+removed+" added pitched roof objects; restored original shared garage shell and snow cap. All garage mesh references and root-relative transforms match Pinefall. Saved/reopened scene, forest/facilities, UI/snow and sampled access checks passed. Roof-only visual change; no Play/device run.");
  }
  static void Review(){var scene=EditorSceneManager.OpenScene(Path);var terrain=All<Terrain>(scene).Single();var placements=All<CatalogPlacement>(scene);Check(placements.Count(p=>p.placementId=="alps-garage")==1&&placements.Count(p=>p.placementId=="alps-fuel-station")==1&&placements.Count(p=>p.placementId=="alps-disposal-yard")==1,"three borrowed facilities");Check(placements.Count(p=>(p.placementId??"").StartsWith("alps-lamp-"))==18,"18 borrowed lamps");Check(placements.Count(p=>(p.placementId??"").StartsWith("alps-sign-"))==5,"five borrowed signs");Check(!All<Transform>(scene).Any(t=>t.name.StartsWith("Alps retained roof |")),"added pitched roof removed");Check(placements.Single(p=>p.placementId=="alps-garage").GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("SnowCap")).All(r=>r.gameObject.activeSelf&&r.enabled),"borrowed garage snow cap enabled");
   int count=0;foreach(var tree in placements.Where(p=>(p.assetId??"").StartsWith("alpine-tree-"))){Check(Vector3.Angle(tree.transform.up,Vector3.up)<.01f,"upright tree");float high=float.MinValue,low=float.MaxValue;foreach(var f in Feet(tree.gameObject)){var point=tree.transform.TransformPoint(f);float clearance=point.y-Ground(terrain,point);low=Mathf.Min(low,clearance);high=Mathf.Max(high,clearance);}Check(low>-.018f&&low<.001f&&high<.18f,"tree mesh support on terrain: "+tree.placementId+" "+low+" / "+high);var lod=tree.GetComponent<DistanceVisibility>();Check(lod.distance==200&&lod.distantDistance==2000&&lod.switchBuffer==12,"existing tree view distances");count++;}Check(count==System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(Log+"/TheAlps-before.unity"),"  placementId: alps-tree-").Count,"actual saved forest count retained");
   // Service/recovery and open yard approach are checked against actual scene colliders.
   Physics.SyncTransforms();var routePoints=new List<Vector3>();for(float z=-70;z>=-94;z-=2)routePoints.Add(new Vector3(-95,6.9f,z));for(float z=-65;z>=-88;z-=2)routePoints.Add(new Vector3(94,6.9f,z));routePoints.Add(new Vector3(-89,6.9f,-90));foreach(var at in routePoints){var hits=Physics.OverlapBox(at,new Vector3(1.8f,1.5f,1.8f),Quaternion.identity,1,QueryTriggerInteraction.Ignore).Where(c=>!(c is TerrainCollider)&&!c.GetComponentInParent<SnowField>()).ToArray();Check(hits.Length==0,"vehicle route blocked at "+at+": "+string.Join(",",hits.Select(c=>c.name)));}
   Check(All<Light>(scene).Count(l=>l.type==LightType.Directional)==1,"single sun");ProductionMenuChecks.ValidateAuthored(All<PrototypeHUD>(scene).Single());MechanicsChecks.Run();Capture(scene);EditorSceneManager.OpenScene(Path);File.WriteAllText(Log+"/Validation.txt","PASS: saved/reopened Alps borrowed garage/fuel/disposal, 18 lamps, five signs; original borrowed garage roof/snow cap restored, Swiss red gates. 374 upright terrain-seated forest objects with retained LOD and colliders. Service/recovery/yard approach sampled clear. UI bindings and snow ledger checks passed. Physical driving, Android rendering/performance remain separate acceptance.");
  }
  static void Capture(Scene scene){var session=All<PrototypeSession>(scene).Single();var camera=session.CameraRig.view;var hud=session.HUD.gameObject;bool active=hud.activeSelf;var p=camera.transform.position;var r=camera.transform.rotation;var target=camera.targetTexture;float fov=camera.fieldOfView;bool orthographic=camera.orthographic;var rt=RenderTexture.GetTemporary(1600,900,24);try{hud.SetActive(false);camera.targetTexture=rt;camera.orthographic=false;camera.fieldOfView=55;foreach(string shot in new[]{"Depot","Yard","Forest","Town"}){camera.transform.position=shot=="Depot"?new Vector3(-61,28,-60):shot=="Yard"?new Vector3(126,28,-53):shot=="Forest"?new Vector3(-160,90,220):new Vector3(245,210,-290);camera.transform.LookAt(shot=="Depot"?new Vector3(-99,9,-98):shot=="Yard"?new Vector3(94,7,-85):shot=="Forest"?new Vector3(-80,20,70):new Vector3(0,12,30));camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();File.WriteAllBytes(Log+"/"+shot+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);RenderTexture.active=old;}}finally{hud.SetActive(active);camera.targetTexture=target;camera.transform.SetPositionAndRotation(p,r);camera.fieldOfView=fov;camera.orthographic=orthographic;RenderTexture.ReleaseTemporary(rt);}}
 }
}
